 static class GlassLayout extends LinearLayout{Paint paint=new Paint(3);public GlassLayout(Context c){super(c);setWillNotDraw(false);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){int w=getWidth(),h=getHeight();paint.setShader(new android.graphics.LinearGradient(0,0,w,h,new int[]{0xCC123247,0x7010263A,0x55101A27},null,android.graphics.Shader.TileMode.CLAMP));c.drawRoundRect(0,0,w,h,dpF(24),dpF(24),paint);paint.setShader(new android.graphics.LinearGradient(0,0,w,0,new int[]{0x00FFFFFF,0x55B8F4FF,0x00FFFFFF},null,android.graphics.Shader.TileMode.CLAMP));paint.setStrokeWidth(dpF(1));paint.setStyle(Paint.Style.STROKE);c.drawRoundRect(dpF(.5f),dpF(.5f),w-dpF(.5f),h-dpF(.5f),dpF(24),dpF(24),paint);paint.setStyle(Paint.Style.FILL);paint.setShader(null);super.onDraw(c);}float dpF(float x){return x*getResources().getDisplayMetrics().density;}}
