 static class HudBackgroundDrawable extends android.graphics.drawable.Drawable{Paint p=new Paint(3);public void draw(Canvas c){int w=getBounds().width(),h=getBounds().height();p.setShader(new android.graphics.LinearGradient(0,0,w,h,new int[]{0xFF020711,0xFF031522,0xFF020810},new float[]{0,.55f,1},android.graphics.Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(new android.graphics.RadialGradient(w*.82f,h*.12f,w*.7f,new int[]{0x6530CFFF,0x15207EAA,0x00000000},null,android.graphics.Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(new android.graphics.RadialGradient(w*.12f,h*.78f,w*.65f,new int[]{0x3A005D9A,0x0D074E72,0x00000000},null,android.graphics.Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);p.setColor(0x1238B9E8);p.setStrokeWidth(1);float step=dpF(28);for(float x=0;x<w;x+=step)c.drawLine(x,0,x,h,p);for(float y=0;y<h;y+=step)c.drawLine(0,y,w,y,p);}public void setAlpha(int a){}public void setColorFilter(android.graphics.ColorFilter f){}public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}float dpF(float x){return x*Resources.getSystem().getDisplayMetrics().density;}}
 void nav(){nav.removeAllViews();String[] labels={t("Главная","Home"),t("ТО","Service"),t("Финансы","Finance"),t("Авто","Auto"),t("Ещё","More")};int[] icons={R.drawable.ic_nav_home,R.drawable.ic_nav_service,R.drawable.ic_nav_finance,R.drawable.ic_nav_car,R.drawable.ic_nav_more};for(int i=0;i<labels.length;i++){final int p=i;LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);ImageView ic=new ImageView(this);ic.setImageResource(icons[i]);ic.setColorFilter(screen==p?blue:sub());TextView v=text(labels[i],10,screen==p);v.setGravity(Gravity.CENTER);v.setTextColor(screen==p?blue:sub());item.addView(ic,new LinearLayout.LayoutParams(-1,dp(34)));item.addView(v,new LinearLayout.LayoutParams(-1,dp(22)));if(screen==p){GradientDrawable activeBg=new GradientDrawable();activeBg.setColor(0x4425CFFF);activeBg.setCornerRadius(dp(17));activeBg.setStroke(dp(1),0x9931DFFF);item.setBackground(activeBg);}item.setOnClickListener(x->{screen=p;subPage=0;render();});nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}}
 String val(String key,String def){Cursor c=db.raw("SELECT "+key+" FROM vehicle WHERE id=?",new String[]{String.valueOf(active)});try{return c.moveToFirst()?c.getString(0):def;}finally{c.close();}}
 double num(String s){try{return Double.parseDouble((s==null?"":s).replace(" ","").replace(",","."));}catch(Exception e){return 0;}}
 String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 void setupAuto(EditText e,String hint){if(!(e instanceof AutoCompleteTextView))return;AutoCompleteTextView a=(AutoCompleteTextView)e;String[] base=suggestionValues(hint);ArrayAdapter<String> ad=new ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,base){@Override public View getView(int p,View c,android.view.ViewGroup parent){TextView v=(TextView)super.getView(p,c,parent);v.setTextColor(fg());v.setTextSize(14);v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackgroundColor(0xF00A1824);return v;}};a.setAdapter(ad);a.setThreshold(1);}
 String[] suggestionValues(String hint){String h=hint.toLowerCase(Locale.ROOT);if(h.contains("марка")||h.contains("brand"))return new String[]{"Volkswagen","BMW","Mercedes-Benz","Audi","Toyota","Lada","Kia","Hyundai","Skoda","Ford","Honda","Nissan","Mazda","Volvo","Porsche","Renault","Geely","Chery","Haval"};if(h.contains("модель")||h.contains("model")){String b=val("brand","").toLowerCase(Locale.ROOT);if(b.contains("volkswagen")||b.equals("vw"))return new String[]{"Polo","Golf","Passat","Tiguan","Touareg","Jetta","Taos"};if(b.contains("bmw"))return new String[]{"X1","X3","X5","X6","3 Series","5 Series","7 Series"};if(b.contains("toyota"))return new String[]{"Camry","RAV4","Corolla","Land Cruiser","C-HR"};if(b.contains("kia"))return new String[]{"Rio","Ceed","Sportage","K5","Sorento"};if(b.contains("audi"))return new String[]{"A3","A4","A6","Q3","Q5","Q7"};return new String[]{"Polo","Golf","X5","Camry","RAV4","Rio","Ceed","Octavia","Focus","Solaris"};}if(h.contains("год")||h.contains("year")){ArrayList<String> y=new ArrayList<>();for(int i=2026;i>=1990;i--)y.add(String.valueOf(i));return y.toArray(new String[0]);}if(h.contains("двиг")||h.contains("engine"))return new String[]{"1.0 TSI","1.2","1.4 TSI","1.5 TSI","1.6","1.8 TSI","2.0 TSI","2.0 TDI","2.5","3.0","Электро"};if(h.contains("объём")||h.contains("volume"))return new String[]{"1.0","1.2","1.4","1.5","1.6","1.8","2.0","2.5","3.0","4.0"};if(h.contains("мощ")||h.contains("power"))return new String[]{"90","100","110","120","125","150","180","200","250","300","400"};if(h.contains("привод")||h.contains("drive"))return new String[]{"Передний","Задний","Полный","4x4","AWD"};if(h.contains("топливо")||h.contains("fuel"))return new String[]{"АИ-92","АИ-95","АИ-98","АИ-100","Дизель","Газ","Гибрид","Электро"};if(h.contains("короб")||h.contains("gear"))return new String[]{"АКПП","МКПП","CVT","DSG","AMT","AT","DCT"};if(h.contains("категор")||h.contains("category"))return new String[]{"ТО","Ремонт","Топливо","Шины","ОСАГО","Налог","Штраф","Мойка","Парковка","Запчасти","Диагностика","Прочее"};if(h.contains("сезон"))return new String[]{"Лето","Зима","Всесезон"};if(h.contains("статус"))return new String[]{"NEW","DIAGNOSIS","REPAIR","RESOLVED"};if(h.contains("тип")&&h.contains("документ"))return new String[]{"ОСАГО","СТС","ПТС","Диагностическая карта","Договор","Другое"};if(h.contains("размер")&&h.contains("шин"))return new String[]{"185/65 R15","195/55 R16","205/55 R16","215/55 R17","225/45 R18","235/55 R18","255/55 R19"};if(h.contains("станц")||h.contains("азс"))return dbSuggestions("fuel","station");if(h.contains("сервис")||h.contains("service center"))return dbSuggestions("service_center","name");if(h.contains("бренд")||h.contains("brand"))return dbSuggestions("part","brand");if(h.contains("поставщик")||h.contains("supplier"))return dbSuggestions("part","supplier");if(h.contains("название")||h.contains("title")){String[] a=dbSuggestions("service","title");String[] b=dbSuggestions("expense","title");ArrayList<String> z=new ArrayList<>();for(String v:a)z.add(v);for(String v:b)if(!z.contains(v))z.add(v);return z.toArray(new String[0]);}if(h.contains("артикул")||h.contains("part number"))return dbSuggestions("part","partNumber");return new String[0];}
 String[] dbSuggestions(String table,String column){ArrayList<String> out=new ArrayList<>();Cursor c=db.raw("SELECT DISTINCT "+column+" FROM "+table+" WHERE vehicleId=? AND "+column+"<>'' ORDER BY "+column+" LIMIT 30",new String[]{String.valueOf(active)});try{while(c.moveToNext())out.add(c.getString(0));}finally{c.close();}return out.toArray(new String[0]);}
 EditText input(String hint,String value){AutoCompleteTextView e=new AutoCompleteTextView(this);e.setHint(hint);e.setText(value);e.setTextColor(fg());e.setHintTextColor(sub());e.setTextSize(15);e.setSingleLine(true);e.setPadding(dp(14),0,dp(14),0);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0x64182A38,0x32101B25});g.setCornerRadius(dp(15));g.setStroke(dp(1),0xB52AD2FF);e.setBackground(g);e.setDropDownBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0xF0081722));e.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(50)){{setMargins(0,0,0,dp(8));}});setupAuto(e,hint);return e;}
ArrayAdapter<String> adapterFor(String[] values){return new ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,values){@Override public View getView(int p,View c,android.view.ViewGroup parent){TextView v=(TextView)super.getView(p,c,parent);v.setTextColor(fg());v.setTextSize(14);v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackgroundColor(0xF00A1824);return v;}};}
String[] suggestionValuesForBrand(String brand){String b=(brand==null?"":brand).toLowerCase(Locale.ROOT);if(b.contains("volkswagen")||b.equals("vw"))return new String[]{"Polo","Golf","Passat","Tiguan","Touareg","Jetta","Taos"};if(b.contains("bmw"))return new String[]{"X1","X3","X5","X6","3 Series","5 Series","7 Series"};if(b.contains("mercedes"))return new String[]{"A-Class","C-Class","E-Class","GLA","GLC","GLE","S-Class"};if(b.contains("toyota"))return new String[]{"Camry","RAV4","Corolla","Land Cruiser","C-HR"};if(b.contains("kia"))return new String[]{"Rio","Ceed","Sportage","K5","Sorento"};if(b.contains("audi"))return new String[]{"A3","A4","A6","Q3","Q5","Q7"};return new String[]{"Polo","Golf","X5","Camry","RAV4","Rio","Ceed","Octavia","Focus","Solaris"};}
