void vehicleDialog(boolean first){
 final LinearLayout l=form();
 EditText brand=input(t("Марка","Brand"),first?"":val("brand",""));
 EditText model=input(t("Модель","Model"),first?"":val("model",""));
 brand.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){if(model instanceof AutoCompleteTextView){AutoCompleteTextView ac=(AutoCompleteTextView)model;ac.setAdapter(adapterFor(suggestionValuesForBrand(s.toString())));if(ac.getText().length()>0)ac.showDropDown();}}public void afterTextChanged(Editable e){}});
 EditText year=input(t("Год выпуска","Year"),first?"":val("year",""));year.setInputType(InputType.TYPE_CLASS_NUMBER);
 EditText engine=input(t("Двигатель","Engine"),first?"":val("engine",""));
 EditText volume=input(t("Объём двигателя, л","Engine volume, L"),first?"":val("volume",""));
 EditText power=input(t("Мощность, л.с.","Power, hp"),first?"":val("power",""));power.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);
 EditText drive=input(t("Привод","Drive"),first?"":val("drive",""));
 EditText gear=input(t("Коробка передач","Gearbox"),first?"":val("gear",""));
 EditText mileage=input(t("Текущий пробег, км","Current mileage, km"),first?"0":val("mileage","0"));mileage.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);
 EditText vin=input("VIN",first?"":val("vin",""));
 EditText plate=input(t("Госномер","Plate"),first?"":val("plate",""));
 EditText fuel=input(t("Тип топлива","Fuel type"),first?"":val("fuelType",""));
 EditText color=input(t("Цвет","Color"),first?"":val("color",""));
 EditText note=input(t("Заметка","Note"),first?"":val("note",""));
 Button photo=btn(t("Добавить фото автомобиля","Add vehicle photo"),Color.rgb(64,103,145));l.addView(photo);photo.setOnClickListener(v->pickPhoto());
 for(EditText e:new EditText[]{brand,model,year,engine,volume,power,drive,gear,mileage,vin,plate,fuel,color,note})l.addView(e);
 Button save=btn(t("Сохранить автомобиль","Save vehicle"),blue);l.addView(save);
 addDialogCard(t(first?"Новый автомобиль":"Профиль автомобиля",first?"New vehicle":"Vehicle profile"),l);
 save.setOnClickListener(v->{
  String b=brand.getText().toString().trim(),m=model.getText().toString().trim();double km=num(mileage.getText().toString());int y=(int)num(year.getText().toString());
  if(b.isEmpty()||m.isEmpty()||!validNonNegative(km)){toast(t("Заполните марку, модель и корректный пробег","Enter brand, model and valid mileage"));return;}
  if(y!=0&&(y<1886||y>Calendar.getInstance().get(Calendar.YEAR)+1)){toast(t("Проверьте год выпуска","Check production year"));return;}
  ContentValues x=new ContentValues();x.put("brand",b);x.put("model",m);x.put("year",y);x.put("engine",engine.getText().toString().trim());x.put("volume",volume.getText().toString().trim());x.put("power",power.getText().toString().trim());x.put("drive",drive.getText().toString().trim());x.put("gear",gear.getText().toString().trim());x.put("mileage",km);x.put("vin",vin.getText().toString().trim());x.put("plate",plate.getText().toString().trim());x.put("fuelType",fuel.getText().toString().trim());x.put("color",color.getText().toString().trim());x.put("note",note.getText().toString().trim());String chosenPhoto=attachment();x.put("photo",chosenPhoto.isEmpty()?(first?"":val("photo","")):chosenPhoto);x.put("createdAt",System.currentTimeMillis());
  if(first){active=db.addVehicle(x);getPreferences(0).edit().putLong("active",active).apply();db.log(active,"AUTO","Автомобиль добавлен",b+" "+m);screen=0;subPage=0;render();}else{double oldKm=num(val("mileage","0"));if(km<oldKm){new AlertDialog.Builder(this).setTitle(t("Пробег меньше текущего","Mileage is lower")).setMessage(t("Сохранить меньший пробег? Текущий пробег автомобиля не будет автоматически уменьшен.","Save lower mileage? The current vehicle mileage will not be lowered automatically.")).setNegativeButton(t("Отмена","Cancel"),null).setPositiveButton(t("Сохранить","Save"),(dd,ww)->{db.update("vehicle",x,"id=?",new String[]{String.valueOf(active)});toast(t("Профиль сохранён","Profile saved"));render();}).show();}else{db.update("vehicle",x,"id=?",new String[]{String.valueOf(active)});toast(t("Профиль сохранён","Profile saved"));render();}}
 });
 nav.setVisibility(View.GONE);
}
