 void home(){if(active<0){showWelcome();return;}String vehicle=(val("brand","")+" "+val("model","")).trim();header("AUTO HUB",vehicle);GlassLayout hero=(GlassLayout)card();hero.setPadding(dp(18),dp(18),dp(18),dp(18));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(text(vehicle,25,true));String meta=(val("year","").equals("0")?"":val("year","")+"  ·  ")+val("engine","")+((val("gear","").isEmpty())?"":"  ·  "+val("gear",""));info.addView(small(meta));top.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button edit=btn("ПРОФИЛЬ",blue);edit.setTextSize(10);edit.setOnClickListener(v->editVehicle());top.addView(edit,new LinearLayout.LayoutParams(dp(105),dp(42)));hero.addView(top);addGap(8);ImageView car=new ImageView(this);String carUri=val("photo","");if(carUri.isEmpty())car.setImageDrawable(vehicleDrawable());else try{String resolved=resolveAttachment(carUri);if(resolved.startsWith("/"))car.setImageURI(Uri.fromFile(new File(resolved)));else car.setImageURI(Uri.parse(resolved));}catch(Exception ignored){car.setImageDrawable(vehicleDrawable());}car.setAdjustViewBounds(true);car.setScaleType(ImageView.ScaleType.CENTER_INSIDE);hero.addView(car,new LinearLayout.LayoutParams(-1,dp(190)));LinearLayout statusRow=new LinearLayout(this);statusRow.setGravity(Gravity.CENTER_VERTICAL);LinearLayout kmBlock=new LinearLayout(this);kmBlock.setOrientation(LinearLayout.VERTICAL);kmBlock.addView(small(t("ТЕКУЩИЙ ПРОБЕГ","CURRENT MILEAGE")));kmBlock.addView(text(fmt(num(val("mileage","0")))+" км",31,true));statusRow.addView(kmBlock,new LinearLayout.LayoutParams(0,-2,1));TextView status=text(healthText(),11,true);status.setGravity(Gravity.CENTER);status.setTextColor(healthColor());GradientDrawable sg=new GradientDrawable();sg.setColor(0x321ACBFF);sg.setCornerRadius(dp(18));sg.setStroke(dp(1),healthColor());status.setBackground(sg);statusRow.addView(status,new LinearLayout.LayoutParams(dp(125),dp(48)));hero.addView(statusRow);add(hero);addGap(15);sectionTitle(t("КОНТРОЛЬ ОБСЛУЖИВАНИЯ","SERVICE CONTROL"));GlassLayout service=(GlassLayout)card();service.addView(small(t("БЛИЖАЙШЕЕ ОБСЛУЖИВАНИЕ","NEXT SERVICE")));service.addView(text(nextService(),18,true));service.addView(small(t("Расчёт выполняется только по сохранённым данным автомобиля.","Calculated from saved vehicle data only.")));add(service);addGap(14);sectionTitle(t("БЫСТРЫЕ ДЕЙСТВИЯ","QUICK ACTIONS"));LinearLayout q=new LinearLayout(this);q.setOrientation(LinearLayout.HORIZONTAL);String[] labels={"＋ ТО","＋ ЗАПРАВКА","＋ РАСХОД","＋ НАПОМИНАНИЕ"};View.OnClickListener[] ls={v->serviceDialog(),v->fuelDialog(),v->expenseDialog(),v->reminderDialog()};for(int i=0;i<4;i++){Button b=btn(labels[i],blue);b.setTextSize(9);b.setOnClickListener(ls[i]);q.addView(b,new LinearLayout.LayoutParams(0,dp(52),1){{setMargins(dp(3),0,dp(3),0);}});}add(q);addGap(15);sectionTitle(t("КЛЮЧЕВЫЕ ПОКАЗАТЕЛИ","KEY METRICS"));LinearLayout m=new LinearLayout(this);m.setOrientation(LinearLayout.HORIZONTAL);m.addView(metric(t("Пробег","Mileage"),fmt(num(val("mileage","0"))),"км"),new LinearLayout.LayoutParams(0,dp(112),1));m.addView(metric(t("Расход","Consumption"),consumption(),"л/100 км"),new LinearLayout.LayoutParams(0,dp(112),1));m.addView(metric(t("Стоимость/км","Cost/km"),costKm(),"₽/км"),new LinearLayout.LayoutParams(0,dp(112),1));add(m);addGap(15);sectionTitle(t("ПОСЛЕДНЯЯ АКТИВНОСТЬ","RECENT ACTIVITY"));activityCards(4);}
 View metric(String title,String value,String unit){GlassLayout c=(GlassLayout)card();c.setPadding(dp(12),dp(11),dp(12),dp(11));TextView lab=small(title.toUpperCase(Locale.ROOT));lab.setTextSize(10);c.addView(lab);TextView b=text(value,18,true);b.setTextColor(Color.rgb(232,249,255));b.setPadding(0,dp(7),0,dp(2));c.addView(b);c.addView(small(unit));return c;}
