 header(t("Финансы","Finance"),t("Фактические расходы автомобиля","Actual vehicle spending"));
 LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.HORIZONTAL);int[] days={7,30,90,365,0};String[] labels={"7д","30д","90д","1г","Всё"};for(int i=0;i<labels.length;i++){final int d=days[i];Button b=btn(labels[i],blue);b.setAlpha(periodDays==d?1f:.55f);b.setTextSize(11);b.setOnClickListener(v->{periodDays=d;render();});p.addView(b,new LinearLayout.LayoutParams(0,dp(44),1){{setMargins(dp(2),0,dp(2),0);}});}add(p);addGap(10);
 double exp=sumPeriod("expense","amount"),fuel=sumPeriod("fuel","total"),svc=sumPeriod("service","cost"),total=exp+fuel+svc;
