 LinearLayout metrics=card();metrics.addView(text(t("Финансовые метрики","Financial metrics"),17,true));metrics.addView(small(t("Стоимость километра","Cost per km")));metrics.addView(text(costKm()+" ₽/км",25,true));metrics.addView(small(t("Расчёт использует фактический диапазон пробега из записей.","Calculated from recorded mileage range.")));add(metrics);addGap(10);
 LinearLayout quick=card();quick.addView(text(t("Быстрый ввод","Quick entry"),16,true));Button e=btn("＋ Расход",blue);e.setOnClickListener(v->expenseDialog());Button f=btn("＋ Заправка",blue);f.setOnClickListener(v->fuelDialog());Button s=btn("＋ ТО",blue);s.setOnClickListener(v->serviceDialog());quick.addView(e);quick.addView(f);quick.addView(s);add(quick);addGap(10);sectionTitle(t("ПОСЛЕДНИЕ ОПЕРАЦИИ","RECENT OPERATIONS"));listSimple("expense","title","amount");
