 LinearLayout financeBar(String title,double value,double total){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);TextView label=small(title+"  ·  "+money(value)+" ₽");box.addView(label);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(total<=0?0:(int)Math.round(value/total*100));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(blue));bar.setTrackTintList(android.content.res.ColorStateList.valueOf(0x553A5568));box.addView(bar,new LinearLayout.LayoutParams(-1,dp(10)));box.setPadding(0,dp(7),0,dp(7));return box;}
View emptyChart(){LinearLayout x=card();x.addView(text(t("Недостаточно данных для графика","Not enough data for chart"),15,true));x.addView(small(t("Добавьте несколько операций, чтобы увидеть динамику.","Add a few records to see the trend.")));return x;}
View neonHistoryChart(){final ArrayList<Double> vals=new ArrayList<>();final ArrayList<String> labels=new ArrayList<>();String where=periodDays>0?" AND date>=date('now','-"+periodDays+" day')":"";Cursor c=db.raw("SELECT date,SUM(amount) v FROM (SELECT date,amount FROM expense WHERE vehicleId=? UNION ALL SELECT date,total amount FROM fuel WHERE vehicleId=? UNION ALL SELECT date,cost amount FROM service WHERE vehicleId=?) WHERE date<>''"+where+" GROUP BY date ORDER BY date",new String[]{String.valueOf(active),String.valueOf(active),String.valueOf(active)});try{while(c.moveToNext()){labels.add(c.getString(0));vals.add(c.getDouble(1));}}finally{c.close();}return new NeonChartView(this,vals,labels,blue);}
static class NeonChartView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);ArrayList<Double> values;ArrayList<String> labels;int color;NeonChartView(Context c,ArrayList<Double> v,ArrayList<String> l,int col){super(c);values=v;labels=l;color=col;setLayerType(View.LAYER_TYPE_SOFTWARE,null);setMinimumHeight(220);}protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();p.setStyle(Paint.Style.FILL);p.setColor(0x33122B3C);c.drawRoundRect(0,0,w,h,dpStatic(getContext(),22),dpStatic(getContext(),22),p);if(values.isEmpty())return;double max=1;for(double v:values)max=Math.max(max,v);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dpStatic(getContext(),1));p.setColor(0x3344DFFF);for(int i=1;i<5;i++){float y=h*i/5f;c.drawLine(dpStatic(getContext(),14),y,w-dpStatic(getContext(),14),y,p);}Path path=new Path();float left=dpStatic(getContext(),16),right=w-dpStatic(getContext(),16),top=dpStatic(getContext(),18),bottom=h-dpStatic(getContext(),28);for(int i=0;i<values.size();i++){float x=values.size()==1?(left+right)/2:left+(right-left)*i/(float)(values.size()-1);float y=bottom-(float)(values.get(i)/max)*(bottom-top);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setColor(color);p.setStrokeWidth(dpStatic(getContext(),3));p.setShadowLayer(dpStatic(getContext(),8),0,0,0xAA18C8FF);c.drawPath(path,p);p.clearShadowLayer();p.setStyle(Paint.Style.FILL);for(int i=0;i<values.size();i++){float x=values.size()==1?(left+right)/2:left+(right-left)*i/(float)(values.size()-1);float y=bottom-(float)(values.get(i)/max)*(bottom-top);p.setColor(Color.WHITE);c.drawCircle(x,y,dpStatic(getContext(),3),p);}p.setColor(0x7791AFC2);p.setTextSize(dpStatic(getContext(),10));if(!labels.isEmpty()){c.drawText(labels.get(0),left,bottom+dpStatic(getContext(),18),p);String last=labels.get(labels.size()-1);float tw=p.measureText(last);c.drawText(last,right-tw,bottom+dpStatic(getContext(),18),p);}}static float dpStatic(Context c,float x){return x*c.getResources().getDisplayMetrics().density;}}
void statisticsScreen(){
 header(t("Статистика","Statistics"),t("Данные рассчитываются только из локальной базы","Calculated from local database only"));
 LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.HORIZONTAL);int[] days={7,30,90,365,0};String[] labels={"7д","30д","90д","1г","Всё"};for(int i=0;i<labels.length;i++){final int d=days[i];Button b=btn(labels[i],periodDays==d?blue:Color.rgb(55,78,104));b.setTextSize(11);b.setOnClickListener(v->{periodDays=d;render();});p.addView(b,new LinearLayout.LayoutParams(0,dp(44),1){{setMargins(dp(2),0,dp(2),0);}});}add(p);addGap(10);
 double e=sumPeriod("expense","amount"),f=sumPeriod("fuel","total"),sv=sumPeriod("service","cost"),total=e+f+sv;
 LinearLayout summary=card();summary.addView(text(t("Сводка","Summary"),18,true));summary.addView(text(total>0?money(total)+" ₽":t("Недостаточно данных","Not enough data"),29,true));summary.addView(small(t("Расходы "+money(e)+" ₽ · топливо "+money(f)+" ₽ · ТО "+money(sv)+" ₽","Other "+money(e)+" ₽ · fuel "+money(f)+" ₽ · service "+money(sv)+" ₽")));add(summary);addGap(10);
 if(total>0){add(neonHistoryChart());addGap(10);}else add(emptyChart());
 LinearLayout fuelCard=card();fuelCard.addView(text(t("Топливо","Fuel"),17,true));double liters=periodDays==0?sum("fuel","liters"):sumPeriod("fuel","liters");fuelCard.addView(text(liters>0?String.format(Locale.getDefault(),"%.1f л",liters):t("Недостаточно данных","Not enough data"),27,true));fuelCard.addView(small(t("Средний расход: "+consumption()+" л/100 км","Average consumption: "+consumption()+" L/100 km")));add(fuelCard);addGap(8);
 LinearLayout km=card();km.addView(text(t("Пробег и стоимость","Mileage & cost"),17,true));km.addView(text(distance()>0?fmt(distance())+" км":t("Недостаточно данных","Not enough data"),27,true));km.addView(small(t("Стоимость километра: "+costKm()+" ₽/км","Cost per km: "+costKm()+" ₽/km")));add(km);
}

void searchScreen(){header("Поиск","Поиск по локальной базе активного автомобиля");EditText q=input("Введите запрос…","");add(q);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);add(results);Runnable run=()->{results.removeAllViews();String needle=q.getText().toString().trim();if(needle.isEmpty()){results.addView(small("Введите текст для поиска"));return;}String[] tables={"service","fuel","expense","reminder","issue","tire","document","part","service_center"};for(String table:tables){Cursor c=db.all(table,active);try{while(c.moveToNext()){StringBuilder z=new StringBuilder();for(int i=0;i<c.getColumnCount();i++){String s=c.getString(i);if(s!=null)z.append(' ').append(s);}if(z.toString().toLowerCase(Locale.ROOT).contains(needle.toLowerCase(Locale.ROOT))){LinearLayout card=card();card.addView(text(table+" · "+z.toString().trim(),13,true));results.addView(card);Space sp=new Space(this);results.addView(sp,new LinearLayout.LayoutParams(1,dp(6)));}}}finally{c.close();}}};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){run.run();}public void afterTextChanged(Editable e){}});run.run();}
 void reminderScreen(){header("Напоминания","Дата / пробег / повтор");Button a=btn("+ Добавить напоминание",blue);a.setOnClickListener(v->reminderDialog());add(a);addGap(10);Cursor c=db.all("reminder",active);try{if(!c.moveToFirst()){empty("Нет активных напоминаний",this::reminderDialog);return;}do{long id=c.getLong(0);boolean done=c.getInt(c.getColumnIndexOrThrow("done"))!=0;LinearLayout x=card();x.addView(text(c.getString(c.getColumnIndexOrThrow("title")),14,true));x.addView(small(c.getString(c.getColumnIndexOrThrow("date"))+" · "+(c.getDouble(c.getColumnIndexOrThrow("mileage"))>0?fmt(c.getDouble(c.getColumnIndexOrThrow("mileage")))+" км":"без пробега")));x.addView(small(done?"ВЫПОЛНЕНО":"АКТИВНО"));if(!done){Button doneBtn=btn("Выполнено",Color.rgb(40,180,125));doneBtn.setOnClickListener(v->{ContentValues z=new ContentValues();z.put("done",1);db.update("reminder",z,"id=?",new String[]{String.valueOf(id)});ReminderWorker.cancel(this,id);render();});x.addView(doneBtn);}Button edit=btn("Изменить",blue);edit.setOnClickListener(v->reminderDialog(id));x.addView(edit);add(x);addGap(7);}while(c.moveToNext());}finally{c.close();}}
 void activityScreen(){header("Лента активности","Новые события сверху");Cursor c=db.all("activity",active);try{if(!c.moveToFirst()){empty("История пока пуста",()->{});return;}do{LinearLayout x=card();x.addView(text(c.getString(c.getColumnIndexOrThrow("title")),14,true));x.addView(small(c.getString(c.getColumnIndexOrThrow("kind"))+" · "+c.getString(c.getColumnIndexOrThrow("date"))+" "+c.getString(c.getColumnIndexOrThrow("time"))));x.addView(small(c.getString(c.getColumnIndexOrThrow("detail"))));add(x);addGap(7);}while(c.moveToNext());}finally{c.close();}}
